# ================= Catalogue Priovely =================
# Dessins que les gens choisissent eux-mêmes pour leurs catégories.
# Objectif : Priovely n'embarque plus qu'une seule police d'icônes.

def dashed_ring(r=9.25, cx=12, cy=12, n=8, span=30, w=2.0):
    """Cercle pointillé : n arcs de `span` degrés répartis sur le tour."""
    out = []
    for k in range(n):
        a0 = math.radians(360 * k / n); a1 = a0 + math.radians(span)
        x0, y0 = cx + r * math.cos(a0), cy + r * math.sin(a0)
        x1, y1 = cx + r * math.cos(a1), cy + r * math.sin(a1)
        out.append(ln(f"M{x0:.2f} {y0:.2f}A{r} {r} 0 0 1 {x1:.2f} {y1:.2f}", w))
    return out

